new file mode 100644
index 00000000..8a7b5c3
--- /dev/null
+++ b/packages/hive-store/lib/postgres-store.js
@@ -0,0 +1,749 @@
+// PostgresStore - PostgreSQL storage driver for hive-store
+// Implements the same Store interface as SqliteStore for wire-compatibility
+const { DatabaseSync } = require('node:sqlite');
+const { EventEmitter } = require('node:events');
+const path = require('node:path');
+const fs = require('node:fs');
+const { createPool } = require('./pg/pool.js');
+const { schema } = require('./pg/schema.js');
+const { sql } = require('./pg/sql.js');
+const { unsupported } = require('./pg/unsupported.js');
+const config = require('./pg/config.js');
+
+class PostgresStore extends EventEmitter {
+  constructor(opts = {}) {
+    super();
+    this.opts = { ...config.defaults, ...opts };
+    this.pool = null;
+    this.initialized = false;
+    this.closed = false;
+  }
+
+  async init() {
+    if (this.initialized) return;
+    this.pool = createPool(this.opts);
+    await schema.init(this.pool);
+    this.initialized = true;
+  }
+
+  async saveEvent(event) {
+    if (!this.initialized) await this.init();
+    const { id, pubkey, created_at, kind, tags, content, sig } = event;
+    await this.pool.query(sql.INSERT_EVENT, [
+      id, pubkey, created_at, kind,
+      JSON.stringify(tags), content, sig
+    ]);
+    await this.indexEvent(event);
+    this.emit('event', event);
+    return true;
+  }
```

